    for checking set membership, allowing for false positives. The implementation 
    utilizes optimal bit array size and hash function count based on input parameters. 
    This design focuses on memory efficiency and quick insertions and lookups.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
