        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size (m) and number of hash functions (k)
        self.size = self._calculate_optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_optimal_hash_count(self.size, expected_items)

        # Initialize the bit array as a list of integers to represent bits
        self.bit_array = [0] * ((self.size + 31) // 32)  # Use integers for efficient bit-manipulation

    def _calculate_optimal_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array based on n and p."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _calculate_optimal_hash_count(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generates a hash for the given item and seed."""
        hash_result = hashlib.md5((item + str(seed)).encode('utf-8')).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Adds an item to the Bloom filter."""
        for seed in range(self.hash_count):
            index = self._hash(item, seed)
            self.bit_array[index // 32] |= (1 << (index % 32))  # Set the bit at the index

    def contains(self, item: str) -> bool:
        """Checks if an item is in the Bloom filter."""
        for seed in range(self.hash_count):
            index = self._hash(item, seed)
            if not (self.bit_array[index // 32] & (1 << (index % 32))):  # Check the bit at the index
                return False
        return True

